/* ===================================================================
   ENTRAÎNEMENT v5 : données en clair, chargées avant le moteur.
   ORAL2 : scénarios d'oral en plus de SCEN (data.js), avec grille de 4 critères notés 0 à 2.
   ap (facultatif) : une application concrète par étape de la trame tr, même longueur que tr.
   CLASSEUR : exercices « trouve-le dans ton classeur », chronométrés (30 s, 1 min 30, pas trouvé) ; d = domaine affiché.
   Les clés de progression suivent la position (clx0, clx1…) : ajouter en fin de liste seulement.
   GRILLES : grilles génériques (anciens scénarios de l'épreuve 2, études de cas).
   Chaque scénario porte une clé k stable : la progression S.fr en dépend, ne la change jamais.
   Sources : classe-backend/cours-texte (AA01, AA02, AE01, AE06, AE12, AE13) et classeur/gen_examen20.py.
   =================================================================== */
window.ENTR={
GRILLES:{
 /* scénarios de SCEN (épreuve 2) qui n'ont pas de grille propre */
 oral2:['Écoute et reformulation, sans interrompre','Faits concrets, message en « je »','Outils du cours nommés et bien utilisés (DESC, RAVI, autorité)','Solution concrète, suivi et ton assuré'],
 /* études de cas, épreuve 1 */
 cas:['Compréhension du mandat','Méthode et démarche visibles','Chiffrage juste, unités et arrondis','Sécurité et normes citées','Présentation claire et lisible']
},
ORAL2:[
/* ---------- épreuve 3 : planification et réalisation ---------- */
{k:'o3-raccordement',ep:3,d:5,t:'Présenter un projet de raccordement',
 s:'Un client construit une villa avec pompe à chaleur et installation photovoltaïque. Le jury te demande de présenter le projet de raccordement, de la demande jusqu\'à la mise en service.',
 o:'point de raccordement, avis d\'installation, contrôles de calcul',
 tr:['<b>Partir des données</b> : puissance commandée, consommateurs prévus, raccordement existant ou non, injection éventuelle.','<b>Distinguer le point de raccordement</b> (bornes d\'entrée du coupe-surintensité de raccordement, OIBT art. 2) <b>du point de couplage commun</b>, fixé par le gestionnaire de réseau selon la puissance de court-circuit, la puissance, l\'injection et l\'extension future.','<b>La procédure</b> : permis de construire, délai d\'opposition de 30 jours, puis avis d\'installation au gestionnaire de réseau, avec la demande de raccordement technique pour la pompe à chaleur et le photovoltaïque.','<b>Les contrôles de calcul</b> : dimensionnement sur le fusible, chute de tension, mise au neutre, sélectivité.'],
 g:['Démarche dans l\'ordre, de la demande à la mise en service','Point de raccordement et point de couplage bien distingués','Bons formulaires et bons acteurs (gestionnaire de réseau, installateur)','Justification technique et économique'],
 src:'AE01 §5.8 et §6.1 à §6.4'},
{k:'o3-cable',ep:3,d:4,t:'Justifier un choix de câble',
 s:'Pour une nouvelle alimentation en lotissement, ton chef propose un câble et te demande de justifier la section devant le maître d\'ouvrage.',
 o:'courant admissible, températures, coûts du cycle de vie',
 tr:['<b>La section se choisit</b> sur la température maximale du conducteur et sur les coûts du cycle de vie (acquisition, pertes, pose, durée de vie).','<b>Températures du PE réticulé</b> : 90 °C en continu, 110 °C en urgence, 250 °C en court-circuit. Le régime d\'urgence reste limité dans le temps.','<b>Jamais plus de 100 %</b> du courant admissible, en service normal comme en réalimentation. Câbles en parallèle : même type, même longueur.','<b>Câble de raccordement dimensionné sur le fusible</b>, lu dans le tableau du cours ; au delà de 95 mm² Cu ou 150 mm² Al, il part de la station.'],
 g:['Critères complets : thermique, chute de tension, court-circuit, économie','Tableau lu correctement','Cohérence avec le fusible','Argumentation claire pour un non spécialiste'],
 src:'AE01 §4.1, §4.2 et §4.6'},
{k:'o3-manoeuvre',ep:3,d:5,t:'Expliquer une manœuvre',
 s:'Tu dois interconnecter deux stations transformatrices pour libérer un tronçon. Explique au jury la manœuvre, de la commande à la sécurisation du lieu de travail.',
 o:'commande et ordre de manœuvre, conditions de couplage, 5 règles',
 tr:['<b>Une manœuvre est un travail</b> : une erreur peut provoquer un arc. Équipement selon la directive ESTI 407.','<b>Conditions de couplage</b> : concordance des phases, écart de tension faible, même groupe de couplage ; en parallèle, rapport de puissance et tension de court-circuit proches.','<b>Commande puis ordre de manœuvre</b> : lieu, niveau de tension, cellule, appareil, manœuvre. Un ordre oral est répété avant exécution.','<b>Sécurisation par le responsable des travaux</b> selon les 5 règles de sécurité. En BT, mise à terre obligatoire : retour de tension possible par les onduleurs privés.'],
 g:['Rôles clairs (responsable d\'installation, responsable des travaux)','Étapes dans le bon ordre','Vocabulaire exact','Vérifications systématiques avant et après'],
 src:'AE06 §3.3 et §3.4'},
{k:'o3-chantier',ep:3,d:5,t:'Organiser un chantier de fouille',
 s:'Tu pilotes la pose d\'un câble en fouille dans une rue de village. Présente comment tu prépares et organises le chantier avant le premier coup de pelle.',
 o:'préparation en étapes, relevé des conduites, coordination',
 tr:['<b>Préparer dans l\'ordre</b> : offres, choix de l\'entrepreneur et adjudication, information des autres propriétaires de conduites, des autorités et de la presse, relevé des conduites, autorisation de fouille, signalisation.','<b>Relevé des conduites obligatoire</b> avant tout génie civil (OTConst).','<b>Check-list</b> : droit de conduite, plans des autres réseaux, signalisation avec police, commune et canton, réservation des machines.','<b>Coordonner tôt</b> avec les autres réseaux pour des fouilles communes ; informer les riverains.'],
 g:['Planification structurée','Acteurs identifiés','Ressources et délais maîtrisés','Risques anticipés'],
 src:'AE12 §2.2 et §2.3'},
{k:'o3-securite',ep:3,d:4,t:'La sécurité sur une fouille',
 s:'Sur ton chantier, la fouille atteint 1,8 m et un piéton passe à côté. Le jury te demande quelles mesures de sécurité tu imposes.',
 o:'OTConst, étayage, accès, protection des tiers',
 tr:['<b>Au delà de 1,5 m, on étaie</b> (OTConst), selon les règles de hauteur et d\'espacement du cours.','<b>Largeur minimale</b> de fouille selon la profondeur, tableau du cours.','<b>Accès</b> : échelle dès 0,5 m de profondeur, garde-corps en cas de vide.','<b>Tiers</b> : signalisation convenue avec la police et la commune, déblais déposés sans mettre personne en danger. EPI selon la directive ESTI 407.'],
 g:['Bases légales citées (OTConst, CFST, ESTI)','Analyse des risques','Mesures concrètes et chiffrées','Protection des tiers'],
 src:'AE12 §2.2, §2.3 et §3.4 ; AE06 §3.3.1'},
{k:'o3-tirage',ep:3,d:5,t:'Préparer un tirage de câble',
 s:'Un câble unipolaire doit être tiré sur 250 m en tube, avec deux coudes. Explique au jury comment tu vérifies que le tirage est possible et comment tu l\'organises.',
 o:'effort admissible, frottement, rayon de courbure, température',
 tr:['<b>Effort admissible</b> : F = n · A · σ adm, avec σ adm tiré du tableau (unipolaire Cu 60 N/mm², Al 30 N/mm²). En pratique, 20 000 N au maximum.','<b>Effort de tirage</b> : F = M · g · l · µ, multiplié dans chaque coude. On prend le coefficient de frottement le plus défavorable.','<b>Rayon de courbure</b> minimal : K fois le diamètre, selon le tableau (BT unipolaire isolé plastique : 12 fois).','<b>Pose</b> : température minimale de pose, lubrifier dès le début, tirer sans à-coups ni interruption, surveiller la force en continu, coudes au début du sens de traction.'],
 g:['Formules justes, avec unités','Valeurs de tableau correctes','Logistique : touret, sens de tirage, lubrification','Conclusion vérifiée : condition remplie ou non'],
 src:'AE12 §11.2 et §12.1 à §12.9'},
{k:'o3-dimension',ep:3,d:5,t:'Dimensionner une ligne BT',
 s:'Un hameau à 350 m de la station doit être alimenté. Explique au jury comment tu vérifies le dimensionnement de la ligne.',
 o:'chute de tension, court-circuit, mise au neutre',
 tr:['<b>Tension au client</b> : 230 V ± 10 % (EN 50160), viser ± 6 % pour une nouvelle installation. Au delà d\'environ 200 m, la chute de tension limite la charge.','<b>Chute de tension</b> : formule du cours selon le type de ligne (câble à 60 °C, aérien à 80 °C), puis Δu % = ΔU · 100 / U.','<b>Court-circuit unipolaire</b> : Icc = U ph / (Z tr + 2 · Z L), calculé à 20 °C ; il doit faire déclencher le fusible (mise au neutre).','<b>Conclure</b> : comparer aux limites, choisir la section, dire quelle mesure confirmera le calcul.'],
 g:['Bonne formule selon le type de ligne','Hypothèses annoncées (température, cos φ)','Comparaison aux limites','Conclusion et contrôle proposé'],
 src:'AE01 §5.4 à §5.8'},
{k:'o3-reception',ep:3,d:4,t:'Réceptionner l\'ouvrage',
 s:'La pose est terminée. Le jury te demande comment tu réceptionnes l\'ouvrage et mets le raccordement en service.',
 o:'SIA 118, calibrage, mesures, protocoles',
 tr:['<b>Réception des tubes</b> selon la norme SIA 118, procès-verbal signé par les deux parties.','<b>Calibrage des tubes</b> (déformation maximale admise), inspection vidéo en complément.','<b>Mise en service</b> : section, fusibles, serrages, sectionneur de neutre fermé, couvercles, tube étanchéifié ; mesures de tension, champ tournant et Icc.','<b>Documenter</b> : protocole de mesure de terre (lieu, date, nature du sol, valeur, signature), archivage.'],
 g:['Contrôles complets','Valeurs et seuils corrects','Documentation et traçabilité','Décision de mise en service argumentée'],
 src:'AE12 §4.8 ; AE06 §6.3.2 et §6.5'},
/* ---------- épreuve 2 : conduite et formation ---------- */
{k:'o2-recadrage',ep:2,d:4,t:'Entretien de recadrage',
 s:'Un monteur arrive régulièrement en retard, pour la troisième fois ce mois, et laisse son matériel en désordre. Tu le reçois en entretien.',
 o:'DESC, style assuré, autorité, objectif SMART',
 tr:['<b>Préparer l\'entretien</b> : les faits datés, l\'objectif, un lieu calme.','<b>DESC</b> : décrire les faits, exprimer l\'effet en « je », proposer une solution, énoncer les conséquences.','<b>Chercher la cause avant de juger</b> : on fait au mieux en fonction de son énergie, de son savoir faire, de son savoir être, de son environnement et de ce que l\'on attend de soi.','<b>Style assuré</b> : factuel, en « je », ni agressif ni passif. Expliquer plutôt qu\'imposer : c\'est l\'autorité, pas le pouvoir.','<b>Impliquer</b> : « Que proposes-tu ? ». Fixer un objectif SMART et une date de suivi.'],
 ap:['Note les trois dates et les heures d\'arrivée avant de le voir. Reçois-le seul, au dépôt ou au bureau, pas devant l\'équipe. Ton objectif tient en une phrase : qu\'il soit à l\'heure dès lundi.','D : « Lundi, mercredi et ce matin, tu es arrivé après 7 h 15 et ton matériel n\'était pas rangé. » E : « Ça me met en difficulté, l\'équipe t\'attend pour partir. » S : « J\'aimerais qu\'on trouve comment tu peux être là à 7 h. » C : « L\'équipe part à l\'heure et tout le monde finit à l\'heure. »','Pose une question ouverte, puis tais-toi : « Qu\'est-ce qui se passe en ce moment ? » Un souci de trajet ou de famille (environnement), de la fatigue (énergie) ou une consigne mal comprise (ce que l\'on attend de lui) ne se règlent pas de la même façon.','Dis « je constate trois retards », pas « tu es toujours en retard ». Explique pourquoi l\'heure compte, les collègues qui attendent, la coupure annoncée aux clients, au lieu de « c\'est comme ça ».','Laisse-le proposer d\'abord, puis fixe : « À partir de lundi, tu es au dépôt à 7 h et le matériel est rangé le soir. On fait le point dans deux semaines, vendredi. » Note la date.'],
 g:['Faits objectifs, pas de jugement','Posture assurée','Écoute et implication du collaborateur','Objectif et suivi fixés'],
 src:'AA02 outil 49 (DESC) ; AA01 jour 3, pouvoir et autorité ; AA01 jour 4, problématique 1 et « on fait au mieux en fonction de »'},
{k:'o2-apprenti',ep:2,d:5,t:'Former un apprenti à un geste',
 s:'Tu dois former un apprenti de première année à la confection d\'une boîte de jonction. Présente ta séquence de formation.',
 o:'objectif SMART, RAVI, AFEST, courbe de l\'oubli',
 tr:['<b>Objectif SMART</b>, verbe d\'action observable, niveau de Bloom assumé.','<b>RAVI</b> : rassurer, rendre acteur, valoriser, impliquer.','<b>Formation en situation de travail</b> (AFEST) : droit à l\'erreur, puis séquence réflexive (« Explique-moi ce que tu as fait »).','<b>Réactiver</b> selon la courbe de l\'oubli : après 10 min, le premier jour, la première semaine, le premier mois.'],
 ap:['Annonce-le au jury tel quel : « À la fin de la matinée, l\'apprenti confectionne seul une boîte de jonction sur un câble d\'exercice, en suivant la notice, en 45 minutes. » Un verbe qu\'on peut observer, une condition, un critère, une durée.','Rassurer : « on prend le temps, tu as le droit de te tromper ». Acteur : c\'est lui qui tient l\'outil. Valoriser : « ton dénudage est propre ». Impliquer : « qu\'est-ce que tu veux réussir aujourd\'hui ? »','Montre une fois, puis laisse-le faire sans reprendre l\'outil. Ensuite demande : « Explique-moi ce que tu as fait, et pourquoi dans cet ordre. » C\'est en le disant qu\'il retient.','Fais-lui redire les étapes dix minutes après, refaire une boîte avant la fin de la journée, une autre dans la semaine, puis une dans le mois.'],
 g:['Objectif clair et évaluable','Méthode active adaptée','Vérification des acquis','Posture bienveillante'],
 src:'AA02 outils 3, 8, 16 et 17 ; AA01, courbe de l\'oubli'},
{k:'o2-conflit',ep:2,d:4,t:'Gérer un conflit dans l\'équipe',
 s:'Deux monteurs se disputent sur le partage des tâches et l\'ambiance du chantier se dégrade. Tu interviens.',
 o:'analyse de la situation délicate, DESC',
 tr:['<b>Prendre du recul</b> : analyser la situation délicate et décider d\'intervenir ou non.','<b>Écouter chacun</b>, faire des hypothèses, parler en face à face.','<b>DESC</b> pour exprimer le problème sans attaquer les personnes.','<b>Solution concertée</b>, puis suivi. Adapter l\'approche au profil de chacun.'],
 ap:['Avant d\'y aller, demande-toi ce que la dispute touche : la sécurité, le travail, l\'ambiance ? Ici le chantier se dégrade, donc tu interviens, et le jour même.','Vois-les séparément, cinq minutes chacun : « Raconte-moi comment tu vois les choses. » Reformule ce que tu entends, sans donner raison à personne.','Puis ensemble. D : « Depuis lundi, le ton monte au moment de répartir les tâches. » E : « Ça me gêne, le chantier prend du retard. » S : « Je propose qu\'on écrive la répartition chaque matin. » C : « Chacun sait quoi faire et on finit dans les temps. »','« Qu\'est-ce que vous proposez ? » Note la répartition retenue et refais le point en fin de semaine. Avec un profil dominant, va droit au but. Avec un profil stable, prends le temps d\'expliquer.'],
 g:['Analyse de la situation','Neutralité et écoute','Solution concertée','Suivi prévu'],
 src:'AA02 outils 48 et 49 ; AA01 jour 2 et 3'},
{k:'o2-feedback',ep:2,d:3,t:'Donner un feedback',
 s:'Après une manœuvre, tu fais un retour à un jeune monteur : le geste était juste, mais il a oublié de répéter l\'ordre de manœuvre.',
 o:'faits, message en « je », points forts et pistes de progrès',
 tr:['<b>Observations étayées par des faits</b>, en « je », sans vérité sur l\'autre.','<b>Points forts d\'abord, puis une piste de progrès</b> précise.','<b>Faire parler</b> : la fenêtre de Johari s\'ouvre quand on demande.','<b>Engagement</b> : la prochaine fois, ce qui change, et quand on en reparle.'],
 ap:['« J\'ai vu que ton geste était sûr et dans le bon ordre. J\'ai aussi remarqué que l\'ordre de manœuvre n\'a pas été répété. » Tu décris ce que tu as vu, pas ce qu\'il est.','Une seule piste, pas une liste : « La prochaine fois, répète l\'ordre à voix haute avant d\'exécuter. » S\'il repart avec trois reproches, il n\'en retient aucun.','« Et toi, comment tu l\'as vécu ? » Il te dit ce que tu ne voyais pas, et il entend ce qu\'il ne voyait pas de lui.','« À la prochaine manœuvre, tu répètes l\'ordre, et on en reparle juste après. »'],
 g:['Faits concrets','Équilibre points forts et piste de progrès','Implication de la personne','Plan d\'action'],
 src:'AA02 outils 8 et 55 ; AA01 jour 1 (Johari)'},
/* jour 4, volée 25-27 : les quatre entretiens de fin de période d'essai, puis MbO, PDCA et les problématiques finales */
{k:'o2-essai-confiance',ep:2,d:4,t:'Fin de période d\'essai, il perd confiance',
 s:'Fin de période d\'essai. Le collaborateur veut bien continuer, sous réserve de certaines modifications : il dit qu\'on lui a confié des responsabilités trop lourdes, trop rapidement, et il perd confiance en lui. Son responsable direct l\'apprécie beaucoup, le trouve investi, mais a le sentiment qu\'il se noie dans un verre d\'eau. Le directeur exige que chaque collaborateur engagé le reste. Tu mènes l\'entretien.',
 o:'situation du collaborateur, besoins motivationnels, réponse concrète',
 tr:['<b>Préparer</b> : l\'historique du collaborateur, tes faits, la date et un lieu privé, sans distraction.','<b>Accueillir et prendre l\'information</b> : sa situation spécifique d\'abord, par des questions ouvertes.','<b>Trouver le besoin motivationnel</b> : ici être rassuré et reconnu. On fait au mieux en fonction de son énergie, de son savoir faire, de son savoir être, de son environnement et de ce que l\'on attend de soi.','<b>Y répondre si c\'est possible</b> : « De quoi as-tu besoin pour y arriver ? » Outils, délégation, formation, organisation.','<b>Conclure clairement</b> : dire si la période d\'essai est terminée ou pas, fixer un objectif SMART et un suivi.'],
 ap:['Relis ce qu\'il a fait depuis son arrivée et note deux réussites précises. Réserve une demi-heure, porte fermée, téléphone coupé.','« Comment vas-tu ? Comment te sens-tu dans l\'entreprise ? » Laisse-le finir, puis reformule : « Si je comprends bien, c\'est allé trop vite pour toi. »','Demande-lui ce qui pèse le plus. Si c\'est ce que l\'on attend de lui, le problème vient de la charge confiée, pas de sa valeur. Dis-lui ce que tu vois : « Tu es investi, et je veux que tu reprennes confiance. »','Propose du concret et laisse-le choisir : reprendre une partie des responsabilités pour quelques mois, un collègue référent, une formation. « Qu\'est-ce qui t\'aiderait le plus ? »','« Ta période d\'essai est terminée, tu fais partie de l\'équipe. » Pas de « mais » derrière, il annule ce qui précède. Puis l\'objectif : « D\'ici trois mois, tu conduis seul tel type de chantier, et on fait le point chaque mois. »'],
 g:['Situation du collaborateur prise en compte','Besoin motivationnel identifié','Réponse concrète au besoin','Décision claire et suivi fixé'],
 src:'AA01 jour 4, entretien d\'évaluation 1 et travaux de la classe ; jour 3, Maslow'},
{k:'o2-essai-equipe',ep:2,d:4,t:'Fin de période d\'essai, il veut changer d\'équipe',
 s:'Fin de période d\'essai. Le collaborateur souhaite rester dans l\'entreprise mais changer d\'équipe : son intégration se passe mal, il a un différend personnel avec un membre de l\'équipe actuelle. Son chef direct, qui a plusieurs équipes, le trouve très pointu et perfectionniste. Il souhaite le garder, tout en prolongeant de trois mois sa période d\'essai. Tu mènes l\'entretien.',
 o:'questionner avec empathie, besoin d\'intégration, proposition expliquée',
 tr:['<b>Préparer</b> : les faits, ce que le chef propose, un lieu privé.','<b>Questionner avec empathie</b> : comment ça va, comment ça se passe, quels sont ses besoins, ses points à améliorer.','<b>Trouver le besoin motivationnel</b> : un besoin social, être intégré dans un groupe.','<b>Proposer et faire réagir</b> : changer d\'équipe et prolonger de trois mois. « Tu en penses quoi ? »','<b>Conclure</b> : la décision dite clairement, le premier pas, le suivi.'],
 ap:['Renseigne-toi avant : dans quelle autre équipe il y a une place, et ce que le chef attend de ces trois mois.','« Comment ça se passe dans l\'équipe ? Quels sont tes besoins ? » Quand il parle du différend : « Je comprends. » Tu ne prends pas parti contre le collègue absent.','Son travail n\'est pas en cause, il est pointu. Ce qui manque, c\'est sa place dans le groupe. Dis-le : « Ton travail est précis, on veut te garder. »','« Je te propose de changer d\'équipe et de prolonger ta période d\'essai de trois mois. Ça te permettra de voir si tu te sens vraiment bien chez nous. Tu en penses quoi ? »','« Par quoi vas-tu commencer ? » Fixe la date du changement d\'équipe et un point après un mois.'],
 g:['Questions ouvertes et empathie','Besoin d\'intégration identifié','Proposition expliquée, avis demandé','Décision claire et suivi fixé'],
 src:'AA01 jour 4, entretien d\'évaluation 2 et travaux de la classe ; jour 3, Maslow'},
{k:'o2-essai-conditions',ep:2,d:4,t:'Fin de période d\'essai, il revient sur ses conditions',
 s:'Fin de période d\'essai. Le collaborateur, contrôleur diplômé, est enthousiasmé par l\'entreprise et ses valeurs. Tout en restant positif, il revient sur ses conditions d\'engagement, qu\'il trouve désavantageuses. Son chef direct le considère autonome et veut continuer avec lui, mais estime qu\'il est très jeune et qu\'il lui faut plus d\'expérience pour prétendre à de meilleures conditions. Tu mènes l\'entretien.',
 o:'avant, pendant, après ; reconnaissance ; objectifs à court, moyen et long terme',
 tr:['<b>Avant</b> : l\'historique du collaborateur, ta préparation, la date et le lieu.','<b>Pendant</b> : en privé, sans distraction, en gérant le temps. Accueil, puis prise d\'information actualisée.','<b>Trouver le besoin motivationnel</b> : être reconnu à sa valeur, puis se réaliser.','<b>Répondre autrement que par l\'argent</b> : responsabilité, projet plus complexe, formation, avec des objectifs SMART à court, moyen et long terme.','<b>Résumer, puis suivre</b> : documents, PV, suivi par le chef.'],
 ap:['Vérifie avant l\'entretien ce que tu as le droit de promettre. Si tu ne peux rien changer aux conditions aujourd\'hui, sache déjà quoi proposer à la place.','« Comment vas-tu ? Comment s\'est passée ta période d\'essai, avec les collègues ? » Laisse-le amener lui-même la question des conditions.','Derrière la demande, il veut être reconnu. Commence par là : « Tu es autonome et on veut continuer avec toi. »','Réponds franchement : « Sur les conditions, ce n\'est pas possible aujourd\'hui. Voilà ce qui les fera évoluer. » Puis un chemin daté : une responsabilité cette année, un projet plus complexe ensuite, une formation. La classe a retenu trois horizons : 1 à 3 ans, 3 à 5 ans, 5 à 10 ans.','Reformule ce qui est décidé, écris-le dans un PV que vous gardez tous les deux, et fixe la date où vous reparlerez des conditions.'],
 g:['Entretien structuré : avant, pendant, après','Besoin de reconnaissance identifié','Refus expliqué, alternative concrète et datée','Résumé écrit et suivi'],
 src:'AA01 jour 4, entretien d\'évaluation 3 et travaux de la classe ; jour 3, Maslow'},
{k:'o2-essai-valeurs',ep:2,d:4,t:'Fin de période d\'essai, il reste à l\'écart',
 s:'Fin de période d\'essai. Le collaborateur est confronté à un nouveau système de valeurs auquel il n\'adhère pas, il peine à s\'identifier. Extrêmement positif sur ses tâches, il ne participe que très rarement aux sorties et activités organisées par l\'entreprise. Son chef direct apprécie son implication et sa conscience professionnelle, déplore son isolement dans l\'équipe et souhaite poursuivre avec lui. Tu mènes l\'entretien.',
 o:'remercier, écouter son avis, conditions motivantes',
 tr:['<b>Ouvrir par lui et remercier</b> : comment il va, s\'il est toujours motivé, le remercier pour son travail et son professionnalisme.','<b>Vérifier qu\'il connaît les règles et les valeurs</b> de l\'entreprise, puis demander son avis.','<b>Trouver le besoin motivationnel</b> : être intégré dans un groupe, adhérer à des valeurs. On ne motive pas quelqu\'un directement, on crée des conditions motivantes.','<b>Chercher ensemble</b> comment améliorer la situation.','<b>Conclure</b> : la décision dite clairement, un objectif SMART, un suivi.'],
 ap:['« Comment vas-tu ? Tu es toujours motivé par ton travail ? » Puis : « Merci pour ton sérieux, on peut compter sur toi sur les chantiers. »','« Est-ce que tu connais nos règles et nos valeurs ? Tu es d\'accord avec ? Dis-moi franchement ce qui te gêne. » Écoute sans défendre l\'entreprise à chaque phrase.','Sépare deux choses : les règles de travail, qui valent pour tous, et les sorties, qui restent libres. Tu ne peux pas l\'obliger à adhérer. Tu peux lui faire une place qui lui convient.','« Comment on pourrait améliorer la situation ? » Par exemple un binôme sur un chantier, une tâche où il transmet ce qu\'il sait, un moment d\'équipe pendant le travail plutôt qu\'une sortie le soir.','« Ta période d\'essai est terminée, on continue ensemble. » Puis un objectif simple et daté, par exemple présenter un point sécurité à l\'équipe d\'ici un mois, et un entretien de suivi.'],
 g:['Remerciements et faits positifs','Avis du collaborateur écouté sans juger','Conditions motivantes proposées, sans contrainte','Décision claire et suivi fixé'],
 src:'AA01 jour 4, entretien d\'évaluation 4 et travaux de la classe ; jour 3, Maslow'},
{k:'o2-mbo',ep:2,d:5,t:'Fixer des objectifs avec ton équipe',
 s:'Ton responsable te demande de fixer avec ton équipe trois objectifs pour l\'année à venir, selon le management par objectifs. Présente ta méthode et tes objectifs.',
 o:'MbO en quatre étapes, objectifs SMART, indicateurs',
 tr:['<b>Des objectifs clairs et mesurables</b>, pas des vœux. SMART : spécifique, mesurable, atteignable, réaliste, temporel.','<b>Impliquer l\'équipe</b> dans la définition de ses objectifs : c\'est ce qui motive et donne un rôle actif.','<b>Suivre régulièrement</b> avec des indicateurs.','<b>Adapter</b> : si un objectif n\'est pas atteint, identifier les blocages et ajuster.'],
 ap:['Transforme « améliorer la fiabilité du réseau » en « réduire les temps de coupure de 15 % sur les interventions de maintenance préventive en un an ». Teste chaque objectif : y a-t-il un chiffre et une échéance ? En classe : rétrofit de 10 postes MT/BT avant fin 2028, engager 2 monteurs pour le dépannage en 2027.','Réunis l\'équipe et demande : « Qu\'est-ce qui nous fait perdre le plus de temps ? » Dans l\'exemple du cours, ce sont les électriciens qui proposent de standardiser certaines réparations. Un objectif qu\'ils ont choisi, ils le portent.','Choisis un ou deux chiffres faciles à relever, comme le nombre de pannes résolues et le temps moyen d\'intervention, et regarde-les chaque mois avec l\'équipe.','Si le temps d\'intervention ne baisse pas, cherche le blocage avant de chercher un coupable. Dans le cours, on organise une formation sur une méthode de diagnostic plus rapide, puis on reprend le suivi.'],
 g:['Objectifs chiffrés et datés (SMART)','Équipe impliquée dans la définition','Indicateurs et rythme de suivi','Ajustement prévu en cas d\'écart'],
 src:'AA01 jour 4, MbO, p. 27 à 35'},
{k:'o2-pdca-securite',ep:2,d:5,t:'Améliorer la sécurité sur tes chantiers',
 s:'Les incidents augmentent sur tes chantiers parce que les EPI ne sont pas toujours portés. On te demande d\'améliorer la sécurité. Présente ta démarche.',
 o:'cycle PDCA, test à petite échelle, mesure',
 tr:['<b>Plan, planifier</b> : identifier le problème et élaborer un plan d\'action.','<b>Do, faire</b> : mettre en œuvre le plan à petite échelle.','<b>Check, vérifier</b> : mesurer les résultats et analyser l\'efficacité du plan.','<b>Act, agir</b> : si le test est concluant, généraliser. Sinon ajuster et recommencer le cycle.'],
 ap:['Commence par les faits : combien d\'incidents, sur quels chantiers, quel EPI manque. Puis le plan du cours : des contrôles et des rappels quotidiens sur site.','Ne change pas tout d\'un coup. Un chef d\'équipe fait une sensibilisation chaque matin pendant une semaine, avec une seule équipe.','Compare avant et après : le port des EPI a-t-il augmenté après les rappels ? Sans chiffre de départ tu ne prouves rien, alors relève-le avant le test.','Si ça marche, la sensibilisation du matin devient une routine pour toutes les équipes. Sinon tu changes le plan et tu refais un tour. La phrase à placer : une petite action de prévention, testée puis généralisée.'],
 g:['Problème décrit par des faits','Test limité avant de généraliser','Mesure avant et après','Décision : généraliser ou ajuster'],
 src:'AA01 jour 4, cycle PDCA, exemple 1 (p. 37 à 45) et problématique 3'},
{k:'o2-rendement',ep:2,d:5,t:'Le rendement a baissé de 15 %',
 s:'Une unité de production a baissé son rendement de 15 % depuis le premier semestre. Tu dois corriger la situation et présenter ta démarche, en reprenant ce que tu as appris depuis le début de la formation.',
 o:'CQQCOQP, autorité, objectif MbO, PDCA',
 tr:['<b>Explorer la situation avant d\'agir</b> : CQQCOQP, comment, quand, qui, combien, où, quoi, pourquoi.','<b>Impliquer l\'équipe</b> : l\'autorité explique et écoute, le pouvoir impose.','<b>Fixer un objectif clair et mesurable</b> (MbO).','<b>Dérouler un PDCA</b> : tester à petite échelle, mesurer, généraliser ou ajuster.'],
 ap:['Pose les sept questions une par une : qu\'est-ce qui a baissé exactement, depuis quand, où, qui est concerné, de combien, comment on le mesure, pourquoi. Tant que la cause n\'est pas trouvée, tu ne proposes rien.','Présente le chiffre à l\'équipe sans chercher de coupable : « On a perdu 15 % depuis le premier semestre. D\'après vous, qu\'est-ce qui a changé ? » Ceux qui font le travail connaissent souvent la cause.','« Retrouver le rendement du premier semestre d\'ici la fin de l\'année », avec un indicateur relevé chaque mois. Un chiffre et une échéance.','Essaie la correction sur une équipe ou sur une semaine, compare avant et après, puis généralise. Si le rendement ne remonte pas, tu ajustes et tu recommences le cycle.'],
 g:['Cause recherchée avant la solution','Équipe impliquée, sans coupable','Objectif chiffré et daté','Test, mesure et ajustement'],
 src:'AA01 jour 4, problématique 2, MbO et PDCA ; jour 1, CQQCOQP ; jour 3, pouvoir et autorité'},
{k:'o2-planifier',ep:2,d:4,t:'Mieux planifier le travail de l\'équipe',
 s:'Ton équipe court après le temps : urgences, matériel oublié, chantiers qui débordent. Vous décidez de mieux planifier votre travail. Présente comment tu t\'y prends.',
 o:'matrice d\'Eisenhower, répartition des ressources, objectif SMART, PDCA',
 tr:['<b>Trier avec la matrice d\'Eisenhower</b> : urgent et important, faire ; urgent et non important, déléguer ; non urgent et important, planifier ; ni l\'un ni l\'autre, éliminer.','<b>Répartir les ressources</b> : le temps, le matériel, les véhicules. C\'est un des dix rôles du manager selon Mintzberg.','<b>Un objectif SMART</b>, décidé avec l\'équipe.','<b>PDCA</b> : essayer, mesurer, garder ou ajuster.'],
 ap:['Liste les tâches de la semaine avec l\'équipe et place chacune dans une case. La panne chez un client : faire. La commande de matériel du mois prochain : planifier, sinon elle deviendra urgente.','Décide la veille qui va où, avec quelle nacelle et quel camion, et fais charger le matériel d\'après une liste écrite.','« D\'ici deux mois, le programme de la semaine est affiché le vendredi et le matériel est chargé la veille, pour chaque chantier. »','Essaie deux semaines avec une équipe, compte les départs retardés avant et après, puis étends aux autres équipes ou corrige.'],
 g:['Priorités triées (urgent, important)','Ressources réparties à l\'avance','Objectif chiffré et daté','Essai, mesure et ajustement'],
 src:'AA01 jour 4, problématique 4, Mintzberg et PDCA ; jour 3, Eisenhower'}
],
/* Classeur : exercices « trouve-le dans ton classeur ». Chaque question pose une petite situation
   d'examen et dit quoi chercher. d = domaine affiché avec l'épreuve (une épreuve seule est trop large).
   r = ce qu'il fallait trouver ; g = où c'est dans le classeur de Gab (épreuve, numéro, page), affiché
   seulement si le réglage « Mon classeur est celui de Gab » est actif ; loi:1 = on cherche un texte de loi.
   8 oct. 2026 : questions réécrites et tous les renvois relus page par page contre le volume du 4 oct. 2026
   (446 pages, ordre des trames) et le fascicule de l'épreuve 2 (17 numéros). Après chaque régénération du
   classeur, relire les g : les pages bougent. Les clés de progression suivent la position (clx0, clx1…) :
   on réécrit sur place, on ajoute en fin de liste seulement. */
CLASSEUR:[
 {ep:2,d:"Formation, objectifs",q:"Tu prépares une formation de deux heures sur la pose d'un coffret. Le jury te demande ton objectif pédagogique. Trouve la fiche qui donne SMART et les niveaux de Bloom.",r:"Objectifs SMART et taxonomie de Bloom, outils n° 3 et 71 : un objectif mesurable, à un niveau d'exigence choisi dans la taxonomie.",g:"Épreuve 2, n° 2, p. 5"},
 {ep:2,d:"Formation, situation délicate",q:"Un collaborateur se braque pendant ton entretien et conteste tout. Trouve la méthode en quatre lettres pour dire ton désaccord sans l'attaquer.",r:"DESC, outil n° 49 : Décrire les faits, Exprimer son ressenti, Solutions, Conclure positivement. Juste avant : outil n° 48, prendre du recul et se poser les 3 questions.",g:"Épreuve 2, n° 9, p. 12"},
 {ep:2,d:"Conduite, gestion du temps",q:"Lundi matin, cinq demandes arrivent en même temps : une panne, un devis, deux appels, un rapport. Trouve l'outil qui te fait trier l'urgent et l'important.",r:"Matrice de priorité d'Eisenhower, outil n° 8. Urgent et important : faire. Important non urgent : planifier.",g:"Épreuve 2, n° 12, p. 16"},
 {ep:2,d:"Formation, motiver le groupe",q:"Tes participants décrochent après la pause. Le jury te demande comment tu les gardes motivés du début à la fin. Trouve l'outil en trois phases et les 7 clefs.",r:"Participants RAVIS, outil n° 17 : au démarrage, durant, à la fin. Avec les 7 clefs de la pédagogie, outil n° 8 des formateurs.",g:"Épreuve 2, n° 4, p. 7"},
 {ep:2,d:"Conduite, style de conduite",q:"Tu reprends une équipe que tu ne connais pas. Trouve le tableau des quatre équipes M1 à M4, pour adapter ton ton et ton style.",r:"Les 4 équipes du cours, M1 à M4 : le projet et le profil de chacune, avec le ton à prendre. Le style adapté à l'équipe est rappelé au n° 13, « Diriger l'équipe ».",g:"Épreuve 2, n° 11, p. 15 (aussi n° 13, p. 17)"},
 {ep:2,d:"Formation, modalités",q:"Tu dois former un apprenti directement sur le chantier, pendant le travail réel. Trouve le sigle de cette modalité et ses points de vigilance.",r:"AFEST, outil n° 16 : action de formation en situation de travail, avec une séquence réflexive. Vigilance : démarche préparée, droit à l'erreur, objectifs partagés, bilan avant et après.",g:"Épreuve 2, n° 3, p. 6"},
 {ep:3,d:"Câbles souterrains, tirage",q:"Tu vas tirer un câble unipolaire en cuivre dans un tube. Avant de tirer, il te faut l'effort maximal. Trouve la formule de la force de traction admissible et la contrainte σ du cuivre unipolaire.",r:"F adm = n · A · σ adm. Cuivre unipolaire : σ adm = 60 N/mm². Jamais plus de 20 000 N.",g:"Épreuve 3, n° 23, p. 178"},
 {ep:3,d:"Câbles souterrains, pose",q:"Ton tracé passe par une chambre avec un coude serré. Le câble est un BT unipolaire à isolation synthétique. Trouve le rayon de courbure minimal.",r:"R min = K × D C. BT unipolaire à isolation synthétique : 12 × le diamètre du câble (10 × en multiconducteur).",g:"Épreuve 3, n° 26, p. 181"},
 {ep:1,d:"Réseau BT, chute de tension",q:"Tu dimensionnes un départ BT pour un nouveau quartier. Le jury demande la chute de tension en pour cent au dernier coffret. Trouve la formule et la limite à viser en installation neuve.",r:"ΔU = √3 · Z60 · I pour un câble, puis Δu % = ΔU · 100 / U. Installation neuve : viser ± 6 %, soit 24 V sur 400 V. Le transformateur ne compte pas dans la chute de tension.",g:"Épreuve 1, n° 14, p. 30 · tabelle du câble au n° 12, p. 27"},
 {ep:1,d:"Réseau BT, court-circuit",q:"Un client est raccordé en bout de ligne, à 300 m de la station. Tu dois vérifier que le fusible fond en cas de défaut. Trouve la formule du courant de court-circuit unipolaire.",r:"Icc = U ph / (Z Tr + 2 · Z L), à 20 °C, avec Z Tr = 8 / S Tr en kVA. Puis comparer à l'Icc minimal du fusible.",g:"Épreuve 1, n° 15, p. 31 · Icc minimal du fusible au n° 17, p. 34"},
 /* lois et références : on apprend à les trouver dans le classeur, pas leur numéro */
 {ep:4,loi:1,d:"Sécurité au travail, EPI",q:"Sur ton chantier, un monteur refuse de porter son casque. Trouve l'article qui oblige le travailleur à utiliser ses EPI.",r:"OPA art. 11 : le travailleur utilise les EPI fournis et ne nuit pas à leur efficacité.",g:"Épreuve 4, n° 83, p. 397 · index « Travailleur, OPA art. 11 »"},
 {ep:4,loi:1,d:"Sécurité au travail, EPI",q:"Ton entreprise veut faire payer ses chaussures de sécurité à un nouveau monteur. Trouve l'article qui dit qui paie les EPI.",r:"OPA art. 90 : les frais des EPI sont à la charge de l'employeur.",g:"Épreuve 4, n° 83, p. 397 · index « Frais des EPI »"},
 {ep:4,loi:1,d:"Sécurité au travail, EPI",q:"Le risque d'arc électrique ne peut pas être supprimé par une mesure technique. Trouve l'article qui oblige l'employeur à fournir des EPI.",r:"OPA art. 5 : l'employeur met les EPI à disposition et veille à leur usage conforme, quand le risque ne s'élimine pas par des mesures techniques ou organisationnelles.",g:"Épreuve 4, n° 83, p. 397 · index « Employeur, OPA art. 5 »"},
 {ep:4,loi:1,d:"Sécurité au travail, EPI",q:"Deux monteurs d'une agence de placement renforcent ton équipe. Trouve l'article qui dit qui surveille le port de leurs EPI.",r:"OPA art. 10 : l'entreprise locataire de services surveille le port des EPI.",g:"Épreuve 4, n° 83, p. 397 · index « Personnel temporaire »"},
 {ep:4,loi:1,d:"Sécurité sur les installations, bases légales",q:"Après un accident, l'inspecteur te demande sur quel texte reposent les obligations de sécurité de l'employeur. Trouve l'article de la LAA.",r:"LAA art. 82 : l'employeur prend les mesures nécessaires selon l'expérience, applicables selon l'état de la technique, adaptées aux conditions. Le travailleur le seconde et porte les EPI.",g:"Épreuve 4, n° 12, p. 261 et 262 · index « LAA art. 82, employeur »"},
 {ep:4,loi:1,d:"Santé et sécurité, bases légales",q:"Un collaborateur se blesse au dos faute de moyen de levage. Trouve l'article du Code des obligations qui oblige l'employeur à protéger sa santé.",r:"CO art. 328 : l'employeur protège la vie et la santé du travailleur.",g:"Épreuve 4, n° 99, p. 426 · index « CO art. 328 »"},
 {ep:4,loi:1,d:"Éclairage public, responsabilité",q:"Un candélabre mal entretenu tombe sur une voiture en stationnement. Trouve l'article qui rend le propriétaire de l'ouvrage responsable.",r:"CO art. 58 : le propriétaire d'un ouvrage répond du défaut d'entretien.",g:"Épreuve 4, n° 93, p. 413 · index « CO art. 58 »"},
 {ep:4,loi:1,d:"Sécurité sur les installations, bases légales",q:"Un passant est blessé par une installation à courant fort que tu exploites. Trouve l'article qui rend l'exploitant responsable.",r:"LIE art. 27 : l'exploitant répond des dommages corporels, sauf force majeure, faute d'un tiers ou faute lourde de la victime.",g:"Épreuve 4, n° 12, p. 261 et 262 · index « LIE art. 27 »"},
 {ep:4,loi:1,d:"Maintenance, bases légales",q:"Tu ouvres une station : schémas pas à jour, inscriptions effacées. Trouve l'article qui oblige l'exploitant à entretenir son installation en permanence.",r:"OICF art. 17 : entretien permanent, installation en parfait état, schémas et inscriptions à jour.",g:"Épreuve 4, n° 85, p. 401 (aussi n° 93, p. 413 et n° 68, p. 376) · index « OICF art. 17 »"},
 {ep:4,loi:1,d:"Maintenance, bases légales",q:"Tu viens de contrôler une station. On te demande combien de temps garder le rapport. Trouve l'article.",r:"OICF art. 19 : les rapports se gardent pendant deux périodes de contrôle.",g:"Épreuve 4, n° 68, p. 376 (aussi n° 93, p. 413) · index « OICF art. 19 »"},
 {ep:4,loi:1,d:"Maintenance, périodicités",q:"Tu planifies les contrôles de l'année pour tes stations et tes lignes aériennes. Trouve le tableau des périodicités maximales par ouvrage.",r:"Périodicité maximale OICF : 5 ans au plus. Stations et cabines : OICF art. 17 à 19. Lignes aériennes HT et BT : OLEI art. 135.3.",g:"Épreuve 4, n° 68, p. 376 · index « Périodicité maximale OICF »"},
 {ep:4,loi:1,d:"Maintenance, câbles",q:"Tu dois couper un câble dans une fouille où passent trois câbles identiques. Trouve l'article qui dit quoi faire avant de travailler dessus.",r:"OLEI art. 140 : identifier le câble sans équivoque, le mettre hors tension et à la terre.",g:"Épreuve 4, n° 75, p. 384 · index « OLEI art. 140 »"},
 {ep:4,loi:1,d:"Maintenance, câbles",q:"Tu poses une ligne en câbles. On te demande où mettre à la terre la gaine. Trouve l'article.",r:"OLEI art. 72 al. 1 : aux deux extrémités, sinon protégée et signalée.",g:"Épreuve 4, n° 75, p. 385 · index « Gaine, OLEI art. 72 al. 1 »"},
 {ep:4,loi:1,d:"Maintenance des équipements",q:"Lors d'un audit, on te demande la preuve des contrôles de tes dispositifs de sécurité. Trouve l'article de l'OPA qui impose de les consigner.",r:"OPA art. 32b : contrôles réguliers, travaux consignés.",g:"Épreuve 4, n° 85, p. 401 (aussi n° 83, p. 398) · index « OPA art. 32b »"},
 {ep:4,loi:1,d:"Exploitation, EPI et risque d'arc",q:"Tu vas retirer un fusible HPC dans une cabine BT. Trouve le tableau qui fixe ta classe d'EPI selon le courant de court-circuit.",r:"ESTI 407 : tableau des classes G, 1, 2 et 3 selon Ik, ou selon le calibre du fusible amont si Ik est inconnu.",g:"Épreuve 4, n° 18, p. 275 · index « Tableau des classes ESTI 407 »"},
 {ep:4,loi:1,d:"Éclairage public, contrôles",q:"Tu contrôles l'éclairage public d'une commune. Trouve la directive de l'ESTI et ses valeurs limites.",r:"ESTI 244 : tension de défaut ≤ 100 V AC, impédance de boucle avec le facteur 0,66, PE du luminaire ≤ 0,5 Ω, DDR 30 mA en 0,3 s.",g:"Épreuve 4, n° 95, p. 416 (aussi n° 94, p. 414) · index « ESTI 244 »"},
 {ep:4,loi:1,d:"Santé et sécurité, bases légales",q:"Un apprenti de 16 ans rejoint ton équipe. Trouve l'ordonnance qui protège les jeunes travailleurs.",r:"OLT 5 : protection des jeunes travailleurs. Travaux dangereux interdits aux moins de 18 ans.",g:"Épreuve 4, n° 99, p. 426 et 427 · index « LTr, OLT 1 à 5 »"},
 {ep:4,loi:1,d:"Santé et sécurité, chantier",q:"Sur ton chantier, la fouille fait 1,8 m de profondeur. Trouve la règle de blindage.",r:"OTConst : fouille de plus de 1,5 m étayée ou talutée, blindage qui dépasse d'au moins 15 cm.",g:"Épreuve 4, n° 100, p. 430 · index « Fouilles selon l'OTConst »"},
 {ep:4,loi:1,d:"Exploitation, dépannage",q:"Tu trouves du matériel de piquet entreposé dans la cellule d'une station. Trouve la règle sur les entrepôts.",r:"OICF art. 34 al. 3 : entrepôts séparés et sécurisés, hors de la zone d'exploitation.",g:"Épreuve 4, n° 21, p. 278 (aussi n° 85, p. 401) · index « Dépanner dans l'ordre »"},
 {ep:4,loi:1,d:"Maintenance, déchets",q:"Tu évacues l'huile usagée d'un transformateur. Trouve le document à remplir.",r:"OMoD : document de suivi pour les mouvements de déchets spéciaux.",g:"Épreuve 4, n° 82, p. 395 · index « Document de suivi OMoD »"},
 {ep:4,loi:1,d:"Maintenance des équipements",q:"On te demande quelle directive encadre l'entretien des équipements de travail, EPI compris. Trouve la directive CFST.",r:"CFST 6512 : équipements de travail, EPI compris.",g:"Épreuve 4, n° 83, p. 397 (aussi n° 12, p. 261) · index « CFST 6512 »"},
 {ep:4,loi:1,d:"Santé et sécurité, bases légales",q:"Ton entreprise doit faire appel à un spécialiste de la sécurité au travail. Trouve la directive.",r:"CFST 6508 : directive MSST, appel aux médecins du travail et autres spécialistes de la sécurité.",g:"Épreuve 4, n° 99, p. 426 · index « CFST 6508 »"},
 {ep:3,loi:1,d:"Lignes aériennes, sécurité",q:"Tu dois remplacer un poteau en bois sur une ligne aérienne. Trouve la directive à suivre.",r:"CFST 6506 : travaux sur les poteaux en bois, contrôle et sécurités contre le renversement.",g:"Épreuve 3, n° 16, p. 160 (aussi n° 1, p. 111) · index « Procédure CFST 6506 »"},
 {ep:3,loi:1,d:"Mise en service, tension de contact",q:"Un défaut dure 2 secondes avant la coupure. Trouve la courbe qui donne la tension de contact admissible.",r:"OICF, annexe 4 : 50 V alternatif et 120 V continu durablement, courbe jusqu'à 5 s.",g:"Épreuve 3, n° 45, p. 229 (aussi épreuve 4, n° 27, p. 296) · index « Courbe de l'annexe 4 de l'OICF »"},
 {ep:1,loi:1,d:"Préparation du travail, devis",q:"Tu réponds à un appel d'offres avec une autre entreprise, en consortium. Trouve sa forme juridique.",r:"CO art. 530 : société simple, responsabilité solidaire des associés.",g:"Épreuve 1, n° 32, p. 59"},
 {ep:1,loi:1,d:"Préparation du travail, contrat",q:"Un client te confie la construction d'une ligne. Trouve la base légale du contrat et la norme qui règle la réception.",r:"CO art. 363, contrat d'entreprise ; norme SIA 118, art. 157 et suivants, pour la réception.",g:"Épreuve 1, n° 33, p. 61 et n° 38, p. 70 · index « SIA 118 »"},
 /* éclairage public, cours AE03 : le prof annonce un examen « basé sur la pratique » (quel contrôle, avec quoi, pourquoi) */
 {ep:4,d:"Éclairage public, contrôle périodique",q:"Tu envoies deux monteurs faire le contrôle périodique des candélabres d'une rue. Trouve la liste des 7 points à leur donner, avec l'appareil pour chacun.",r:"1 isolement (500 V, LED 250 V, au moins 1 MΩ), 2 courant de court-circuit au dernier point lumineux, 3 tension de défaut (100 V au plus), 4 visuel, 5 stabilité mécanique, 6 distances, 7 documentation.",g:"Épreuve 4, n° 94, p. 415 « Contrôle d'un mât : quoi, avec quoi, pourquoi »"},
 {ep:4,d:"Éclairage public, contrôle final",q:"Une rue vient de recevoir 12 candélabres neufs. Avant la mise en service, tu fais le contrôle final de l'installation. Trouve la liste des 10 points, dans l'ordre.",r:"1 isolement, 2 courant de court-circuit, 3 tension de défaut, 4 installation vers le luminaire selon la NIBT, 5 organes de serrage, 6 soulagement de traction des câbles, 7 documentation, 8 distances, 9 gabarit de la route, 10 évaluation en feux tricolores.",g:"Épreuve 4, n° 94, p. 414 « Contrôle final et périodique »"},
 {ep:4,d:"Éclairage public, mesures",q:"Tu mesures la résistance d'isolement d'un départ d'éclairage public à LED. Trouve la tension d'essai et la valeur minimale.",r:"500 V, 250 à 300 V pour les LED. Au moins 1 MΩ (ancien : 500 kΩ). Avant de mesurer : fusible retiré, sectionneur de neutre ouvert.",g:"Épreuve 4, n° 95, p. 416 « Isolement, Icc et tension de défaut »"},
 {ep:4,d:"Éclairage public, mesures",q:"Au dernier candélabre d'une rue, tu mesures une tension de défaut de 130 V. Trouve la limite et ce qu'il faut garantir quand elle est dépassée.",r:"Limite 100 V. Au delà, la coupure doit se faire en 5 s au lieu de 120 s.",g:"Épreuve 4, n° 95, p. 416 « Isolement, Icc et tension de défaut »"},
 {ep:4,d:"Éclairage public, mise au neutre",q:"La mise au neutre d'un candélabre est insuffisante : le fusible ne coupe pas à temps. Trouve les mesures d'amélioration, de la moins chère à la plus chère.",r:"1 coupe-surintensité plus petit ou coupure en 5 s, 2 piquet de terre, 3 équipotentialité, 4 sécurisation du tronçon, 5 section plus grande, 6 isolation du site.",g:"Épreuve 4, n° 95, p. 418 « Améliorer la mise au neutre »"},
 {ep:4,d:"Éclairage public, procès-verbal",q:"Dans ton procès-verbal de contrôle d'un éclairage public, un défaut est classé en orange. Trouve ce que veulent dire rouge, orange et vert.",r:"Rouge : danger, exploitation interdite, mesures d'urgence. Orange : mesures dans les 5 ans. Vert : rien à faire.",g:"Épreuve 4, n° 94, p. 414 « Contrôle final et périodique »"},
 {ep:4,d:"Éclairage public, réception",q:"À la réception d'un éclairage public neuf, tu dois mesurer l'éclairement de la chaussée. Trouve avec quel appareil et dans quelles conditions.",r:"Luxmètre étalonné depuis moins d'un an, temps sec, lampes de plus de 100 h et chaudes (plus de 20 min), tension du réseau relevée en même temps, aucune lumière parasite.",g:"Épreuve 4, n° 98, p. 424 « Réception photométrique et rénovation »"},
 {ep:4,d:"Éclairage public, stabilité",q:"Un candélabre de 25 ans paraît sain à l'œil. Trouve les méthodes qui prouvent sa stabilité.",r:"Flexion 3D, ultrasons, oscillations. Le contrôle visuel ne prouve jamais la stabilité.",g:"Épreuve 4, n° 97, p. 420 « Stabilité et distances »"},
 {ep:4,d:"Éclairage public, distances",q:"Tu poses un candélabre près d'une ligne à haute tension. Trouve la distance à respecter.",r:"Ligne ordinaire : 1,5 m + 0,01 m/kV. Ligne à grande portée : 2,5 m + 0,01 m/kV.",g:"Épreuve 4, n° 97, p. 421 « Distances aux lignes HT »"},
 {ep:4,d:"Éclairage public, prises",q:"Une commune veut une prise pour les décorations de Noël sur un candélabre, à 2 m du sol. Trouve la protection exigée.",r:"Prise sous 2,5 m : DDR 30 mA. Coupure en 5 s au maximum pour les prises sur l'éclairage public.",g:"Épreuve 4, n° 96, p. 419 « Prises de Noël et fusible EP »"},
 {ep:4,d:"Éclairage public, grandeurs",q:"Le jury te demande la différence entre lumen, candela, lux et candela par mètre carré. Trouve le schéma qui relie ces grandeurs de l'éclairage.",r:"Flux en lumen, intensité en candela, éclairement en lux (lumière reçue par m²), luminance en cd/m² (ce que l'œil voit).",g:"Épreuve 4, n° 90, p. 408 « Grandeurs de l'éclairage »"},
 /* 8 oct. 2026 : les étapes des trames, dans l'ordre du classeur (formule à gauche, tabelle à droite) */
 {ep:1,d:"Réseau BT, dimensionner",q:"Étude de cas : on te donne un quartier à raccorder, de la station jusqu'aux coffrets. Tu ne sais plus par où commencer. Trouve la trame qui donne les 7 étapes dans l'ordre.",r:"Trame « dimensionner un réseau BT » : 1 charge de chaque client, 2 charge de chaque cabine (× 0,7), 3 fusible de départ (× 1,6), 4 section selon Tv, 5 chute de tension, 6 court-circuit, 7 transformateur. Chaque étape donne le numéro à ouvrir.",g:"Épreuve 1, n° 5, p. 16"},
 {ep:1,d:"Réseau BT, charges",q:"Étude de cas : une maison individuelle avec pompe à chaleur doit être raccordée. Trouve la tabelle qui donne son fusible d'introduction et la charge à compter.",r:"Puissances de raccordement moyennes : maisons à gauche (avec PAC ou e-mobilité), immeubles à droite. On y lit le fusible d'introduction et la charge maximale au coffret.",g:"Épreuve 1, n° 6, p. 18 et 19"},
 {ep:1,d:"Réseau BT, simultanéité",q:"Étude de cas : trois cabines de distribution en série alimentent 20 maisons. Il te faut la charge à la station. Trouve le facteur de simultanéité et l'exemple corrigé du cumul.",r:"S dim = (Σ S aval) × 0,7 à chaque point de connexion, 3 points cumulés au maximum, en partant du bout du réseau. L'exemple corrigé est sur la page d'en face.",g:"Épreuve 1, n° 7, p. 20 et n° 8, p. 21"},
 {ep:1,d:"Réseau BT, fusibles",q:"Étude de cas : le fusible du client est de 63 A. Tu dois choisir le fusible de départ dans la cabine pour rester sélectif. Trouve la règle et la tabelle.",r:"Échelonnement sélectif : fusible amont ≥ 1,6 × fusible aval, calibre normalisé. La tabelle donne directement le couple amont et aval.",g:"Épreuve 1, n° 9, p. 22"},
 {ep:1,d:"Réseau BT, section du câble",q:"Étude de cas : ton câble de distribution doit porter 180 A dans un quartier d'habitation. Trouve la tabelle de charge admissible selon les heures de pertes Tv.",r:"Valeurs indicatives de Tv à gauche, tabelle « charge admissible et protection maximale » à droite : on y lit la section et le fusible maximal.",g:"Épreuve 1, n° 11, p. 24 et 25"},
 {ep:1,d:"Réseau BT, impédance",q:"Étude de cas : 220 m de câble GKN en aluminium. Tu dois calculer la chute de tension, puis le court-circuit. Trouve la tabelle qui donne R, X, Z à 60 °C et la boucle à 20 °C.",r:"Données électriques du câble BT : R, X, Z en Ω/km à 20 °C et à 60 °C, impédance de boucle à 20 °C, et la colonne jaune en Ω par mètre. C'est la seule tabelle du câble : on y revient pour la chute de tension et pour le court-circuit.",g:"Épreuve 1, n° 12, p. 27"},
 {ep:1,d:"Réseau BT, ligne aérienne",q:"Étude de cas : le dernier tronçon est une ligne aérienne en Aldrey. Trouve la tabelle des impédances à 80 °C et celle du courant admissible.",r:"Ligne aérienne BT : R, X, Z en Ω/km à gauche (colonne 80 °C pour la chute de tension, boucle à 20 °C pour le court-circuit), courant admissible des fils et cordes à droite.",g:"Épreuve 1, n° 13, p. 28 et 29"},
 {ep:1,d:"Réseau BT, court-circuit",q:"Étude de cas : tu as calculé 480 A de court-circuit au coffret du client, protégé par un fusible de 63 A. Trouve la tabelle qui dit si ce fusible fond à temps.",r:"Icc minimal à la terre : fusible de raccordement (réseau, OICF) à gauche, coupe-surintensité général (installation, OIBT) à droite. L'Icc calculé doit dépasser la valeur de la tabelle.",g:"Épreuve 1, n° 17, p. 34 et 35"},
 {ep:1,d:"Réseau BT, règles de calcul",q:"Étude de cas : réseau mixte, un câble puis une ligne aérienne. Tu hésites sur la formule à prendre. Trouve le tableau « quelle formule, quand ».",r:"Formule 1 : chute de tension, ligne câblée. Formule 2 : chute de tension, ligne aérienne. Formule 3 : court-circuit unipolaire. Réseau mixte : formules 1 + 2, puis 3.",g:"Épreuve 1, n° 16, p. 33"},
 {ep:3,d:"Lignes aériennes, tracé",q:"Étude de cas : un tronçon de ligne en fil de cuivre de 5 mm, sans aucun support existant. Trouve la formule du nombre de poteaux et la tabelle des portées maximales.",r:"Portée maximale t* dans la tabelle 6 (fil Cu 5 mm : 50 m). Aucun support sur le tronçon : n = l / t* + 1, arrondi vers le haut, puis t = l / (n − 1).",g:"Épreuve 3, n° 2, p. 112 et 113 · exemple corrigé au n° 3, p. 114"},
 {ep:3,d:"Lignes aériennes, flèche et traction",q:"Étude de cas : ligne en corde Aldrey, portée de 55 m. Le jury demande la flèche maximale et la traction. Trouve les règles et les tabelles.",r:"Flèche max : la plus grande entre + 40 °C et 0 °C + Z. Traction max : la plus grande entre − 20 °C sans Z et 0 °C + Z. Tabelle 3 pour le cuivre, tabelle 4 pour l'alu et l'Aldrey. Portée entre deux colonnes : interpoler.",g:"Épreuve 3, n° 4, p. 116 · tabelles 3 et 4, p. 120 et 121"},
 {ep:3,d:"Lignes aériennes, longueur du poteau",q:"Étude de cas : ligne BT sur terrain plat, flèche de 1,2 m. Trouve la formule de la longueur du poteau et sa profondeur d'implantation.",r:"L = tête + flèche + garde au sol + profondeur, arrondi au mètre. Garde au sol BT : 6 m. Profondeur b = L / 10 + 0,4 m.",g:"Épreuve 3, n° 5, p. 126 · exemples corrigés au n° 6, p. 128"},
 {ep:3,d:"Lignes aériennes, classe du poteau",q:"Étude de cas : tu connais les conducteurs et les deux portées voisines d'un poteau. Trouve comment choisir sa classe de grosseur I, II ou III.",r:"Σ Ø [mm] × a m [m], avec a m = moyenne des deux portées. Jusqu'à 1250 : classe I. Jusqu'à 1800 : II. Jusqu'à 2750 : III. Dimensions et poids dans la tabelle 5.1, en face.",g:"Épreuve 3, n° 9, p. 134 et 135"},
 {ep:3,d:"Lignes aériennes, haubans",q:"Étude de cas : un mât d'arrêt doit être haubané. Trouve la formule de la force dans le hauban et la tabelle à lire.",r:"F A = f × F L. Tabelle 9 : arrêt, ou angle de moins de 135 grades. Tabelle 10 : dérivation, angle de 135 à 200 grades. Tabelle 11 : câble de hauban, traction admissible ≥ F A.",g:"Épreuve 3, n° 10, p. 142 · tabelles 9 et 10, p. 144 et 145"},
 {ep:3,d:"Câbles souterrains, tirage",q:"Étude de cas : tirage d'un câble avec trois coudes et une montée de 8 m. Trouve le formulaire de tirage et les quatre contrôles à faire à la fin.",r:"F L = F C + M · 10 · l · µ par tronçon droit, ± h · 10 · M en pente, × f à chaque coude. À la fin : F max < F adm, pression Z B < Z adm, rayon réel > R min, température > θ adm.",g:"Épreuve 3, n° 27, p. 182 · fiches câbles en face, n° 28, p. 183 · exemple corrigé au n° 30, p. 186"},
 {ep:4,d:"Mise à terre, impédance admissible",q:"Réseau MT à neutre compensé, bobine de 25 A. On te demande l'impédance de terre maximale d'une station. Trouve la formule.",r:"Z E = 2 × U TP / I E sans mesure supplémentaire, ou 4 × U TP / I E avec mesures alternatives. Exemple de la bobine de 25 A : 4 Ω et 8 Ω.",g:"Épreuve 4, n° 106, p. 300 · tensions de contact au n° 27, p. 296"},
 {ep:4,d:"Mise à terre, courant de défaut",q:"Réseau MT à neutre isolé, avec de la ligne aérienne et du câble. Trouve les formules du courant de défaut capacitif.",r:"Aérien : I F = 0,004 · U · l en km. Câble : I F = 0,2 · U · l en km. Puis U E = Z E · I F, à comparer à 2 et 4 × U TP.",g:"Épreuve 4, n° 107, p. 301"},
 {ep:4,d:"Technique de protection, fusibles",q:"Une artère BT a trois fusibles en série. Trouve la trame qui vérifie la coupure en 120 s et la sélectivité.",r:"1 : chaque fusible coupe en 120 s pour l'Icc du bout de son tronçon. 2 : facteur 1,6 entre deux fusibles. Les conditions de mise au neutre sont sur la page d'en face.",g:"Épreuve 4, n° 114, p. 367 · mise au neutre au n° 63, p. 366 · courbes au n° 62, p. 360"}
]};
